def panda_fk(q):
    T = panda_fk_rel(q)
    T[0][3] -= 0.615
    return T


def get_jacobian(q, eps=1e-5):
    T0 = panda_fk(q)
    p0 = [T0[0][3], T0[1][3], T0[2][3]]
    R0 = [[T0[i][j] for j in range(3)] for i in range(3)]
    J = [[0.0] * 7 for _ in range(6)]
    for j in range(7):
        qp = list(q)
        qp[j] += eps
        Tp = panda_fk(qp)
        for i in range(3):
            J[i][j] = (Tp[i][3] - p0[i]) / eps
        # Orientation derivative: dR * R0^T
        dR = [[(Tp[r][c] - R0[r][c]) / eps for c in range(3)] for r in range(3)]
        # omega = vee(dR * R0^T)
        wR = [
            [sum(dR[r][k] * R0[c][k] for k in range(3)) for c in range(3)]
            for r in range(3)
        ]
        J[3][j] = 0.5 * (wR[2][1] - wR[1][2])
        J[4][j] = 0.5 * (wR[0][2] - wR[2][0])
        J[5][j] = 0.5 * (wR[1][0] - wR[0][1])
    return J, p0, R0


def solve_linear_6x6(A, b):
    # Gaussian elimination with partial pivoting
    M = [list(A[i]) + [b[i]] for i in range(6)]
    for i in range(6):
        max_r = i
        for r in range(i + 1, 6):
            if abs(M[r][i]) > abs(M[max_r][i]):
                max_r = r
        M[i], M[max_r] = M[max_r], M[i]
        piv = M[i][i]
        if abs(piv) < 1e-12:
            piv = 1e-12
        for c in range(i, 7):
            M[i][c] /= piv
        for r in range(6):
            if r != i:
                f = M[r][i]
                for c in range(i, 7):
                    M[r][c] -= f * M[i][c]
    return [M[i][6] for i in range(6)]


def ik_step(q, target_p, target_R, damping=0.01):
    J, p, R = get_jacobian(q)
    err_p = [target_p[i] - p[i] for i in range(3)]
    # Orientation error: 0.5 * (R_cur x R_target)
    # R_err = target_R * R^T
    Re = [
        [sum(target_R[r][k] * R[c][k] for k in range(3)) for c in range(3)]
        for r in range(3)
    ]
    err_w = [
        0.5 * (Re[2][1] - Re[1][2]),
        0.5 * (Re[0][2] - Re[2][0]),
        0.5 * (Re[1][0] - Re[0][1]),
    ]
    err = err_p + err_w
    # J * J^T + damping * I
    JJT = [
        [
            sum(J[r][k] * J[c][k] for k in range(7))
            + (damping if r == c else 0.0)
            for c in range(6)
        ]
        for r in range(6)
    ]
    y = solve_linear_6x6(JJT, err)
    dq = [sum(J[r][j] * y[r] for r in range(6)) for j in range(7)]
    return dq, err_p, err_w


